export const artMarkup=()=>`<p class="art-instruction">색과 도구를 골라 그려요. 다른 도구로 겹쳐 그리면 어떤 자국이 생길까요?</p><div class="art-tools" role="group" aria-label="그리기 도구">${Object.entries(ART_TOOLS).map(([id,t])=>`<button data-art-tool="${id}" aria-pressed="false">${t.label}</button>`).join('')}</div><div class="art-palette" role="group" aria-label="그림 색">${COLORS.map(([label,color])=>`<button data-art-color="${color}" style="--swatch:${color}" aria-label="${label}" aria-pressed="false"></button>`).join('')}</div><div class="art-adjust"><label>굵기 <input id="art-size" type="range" min="2" max="14" value="4"><output id="art-size-value"></output></label><label>불투명도 <input id="art-opacity" type="range" min="10" max="100" value="100"><output id="art-opacity-value"></output></label></div><p class="art-tool-note" id="art-tool-note"></p><div class="art-paper"><canvas id="art-canvas" width="720" height="440" tabindex="0" aria-label="그림 종이. 방향키로 커서를 옮기고 Shift와 방향키 또는 Space로 그려요"></canvas><span id="art-cursor" hidden aria-hidden="true"></span></div><div class="art-actions"><button id="art-undo">되돌리기</button><button id="art-redo">다시 하기</button><button id="art-clear">새 종이</button><button id="art-download">PNG 파일로 보관</button><button id="art-save" class="primary">이 브라우저에 저장</button></div><p id="art-status" role="status" aria-live="polite"></p><p class="caption">초안 한 장만 이 브라우저에 남아요. 새 종이도 되돌릴 수 있어요. 종이 위에서 Ctrl/⌘+Z로 되돌리고 Shift를 더하면 다시 해요.</p>`;
const STATUS={unavailable:'초안 저장을 사용할 수 없어요. PNG 파일로 보관할 수 있어요.',blocked:'다른 창이 초안을 사용 중이에요. 잠시 뒤 저장을 다시 눌러 주세요.',failed:'초안을 저장하지 못했어요. 그림은 남아 있어요. 저장을 다시 누르거나 PNG로 보관해 주세요.',conflict:'다른 탭에서 그림이 바뀌었어요. PNG로 보관한 뒤 페이지를 다시 열어 주세요.',corrupt:'초안이 손상되어 그대로 보존했어요. 이번 그림은 PNG로 보관해 주세요.','future-version':'더 새 버전의 초안을 보존하고 있어요. 이번 그림은 PNG로 보관해 주세요.','too-large':'초안 저장 크기를 넘었어요. PNG 파일로 보관해 주세요.'};
