 function flush(){if(!doc)return;if(frame!==null){caf(frame);frame=null;}const ctx=composite.getContext('2d');compositeImage.data.set(doc.composite());ctx.putImageData(compositeImage,0,0);getView()?.schoolView?.updateDrawing('art.canvas',composite);panel?.render(composite);}
