  function updateTools(){const t=ART_TOOLS[settings.tool];buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.artTool===settings.tool)));colors.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.artColor===settings.color)));Object.assign($('#art-size'),{min:String(t.min),max:String(t.max),value:String(settings.size)});$('#art-size-value').textContent=`${settings.size}`;$('#art-opacity').value=String(Math.round(settings.opacity*100));$('#art-opacity-value').textContent=`${Math.round(settings.opacity*100)}%`;$('#art-tool-note').textContent={pencil:'가늘고 또렷한 선으로 작은 모양을 그려요.',brush:'부드러운 가장자리의 붓이에요. 새 획을 겹치면 색이 짙어져요.',pastel:'종이가 비치는 거친 자국이에요. 넓은 면을 천천히 채워 봐요.',eraser:'그림의 잉크를 지워 종이가 드러나요.'}[settings.tool];}
