     let result;try{result=await pending;}finally{if(writePending===pending)writePending=null;}
     if(!live()||serial!==operation)return;notice=result.status==='saved'?(doc.epoch===epoch?'이 브라우저에 저장됨':'저장했어요. 그 뒤에 그린 부분은 아직 저장 전이에요.'):STATUS[result.status]??STATUS.failed;
