 return {open(){if(ui.modalOpen)return false;return ui.workshop('자유 그림 작업실',artMarkup(),mount,{kind:'art-workshop'});},applyArt(source){ensure();const c=document.createElement('canvas');c.width=W;c.height=H;const ctx=c.getContext('2d'),height=W*source.height/source.width;ctx.clearRect(0,0,W,H);ctx.drawImage(source,0,(H-height)/2,W,height);doc.replace(ctx.getImageData(0,0,W,H).data);c.width=c.height=1;flush();},restore(view){if(doc)view.schoolView?.updateDrawing('art.canvas',composite);},cancel(){panel?.dispose();},async reset(){if(!canSave())return false;panel?.dispose();generation++;if(writePending)try{await writePending;}catch{}if(!canSave())return false;storageEpoch++;const result=await storage.clear();if(result.status!=='cleared')return false;loaded=true;baseRevision=0;loadStatus='empty';savedEpoch=-1;doc?.reset();flush();return true;},getDocument:()=>doc};
